function debounce(func, wait) {
  let timeoutId; // Closure variable holds the timer

  return function(...args) {
    const context = this;

    // 1. If the user clicked again, clear the old timer
    clearTimeout(timeoutId);

    // 2. Start a brand new timer
    timeoutId = setTimeout(() => {
      // 3. When timer finishes, execute the function with correct context
      func.apply(context, args);
    }, wait);
  };
}

// Usage:
const fetchResults = debounce((query) => {
  console.log('Fetching API for:', query);
}, 500);

// User types fast:
fetchResults('a'); // Timer starts
fetchResults('ap'); // Old timer killed, new timer starts
fetchResults('app'); // Old timer killed, new timer starts
// (500ms later) -> Output: "Fetching API for: app"
